def _build_target(manifest) -> tuple[str, list[str]]:
    """(build.sh profile, implied cargo features) for a season."""

    if manifest.challenge_profile == "lite-L1":
        return "L1", ["scaled"]
    return str(manifest.difficulty_index), []


def _receipt_key(path):
    if not path:
        return None
    return sc.Keypair.load(Path(path))


def _signed(work, key, entry) -> dict | None:
    if key is None:
        return None
    from ares_lite.transparency import sign_receipt

    manifest = work.manifest()
    if manifest.receipt_signer and key.public.hex() != manifest.receipt_signer:
        raise SystemExit("receipt key does not match the manifest's receipt_signer")
    receipt = sign_receipt(key, manifest.manifest_hash(), entry).to_json()
    with open(work.path / "receipts_signed.jsonl", "a") as handle:
        handle.write(json.dumps(receipt, sort_keys=True) + "\n")
    return receipt


def _print(obj) -> None:
    print(json.dumps(obj, indent=2, sort_keys=True))


def _beacon(args, slot: int) -> Beacon:
    if getattr(args, "rpc", None):
        # The first produced block at/after the declared slot is the beacon.
        _, value = sc.Rpc(args.rpc).beacon(slot)
        return Beacon("solana-slot-blockhash", slot, value.hex())
    if not args.test_beacon:
        raise SystemExit("need --rpc (real beacon) or --test-beacon HEX (localnet only)")
    return Beacon("test-fixed", slot, args.test_beacon)


