def cmd_new_season(args) -> None:
    manifest = SeasonManifest(
        schema=domains.SEASON_MANIFEST,
        season_id=args.season_id,
        name=args.name,
        network=args.network,
        chain_id=args.chain_id,
        protocol_version=1,
        difficulty_index=args.difficulty,
        adjustment_epoch=0,
        challenge_beacon_slot=args.beacon_slot,
        reward_beacon_delay_slots=args.delay,
        rewards=RewardRules(args.cap, args.threshold_bps, args.seeds, args.cases),
        baseline_source_sha256=source_sha256(),
        financial_value=False,
        notes=tuple(args.note or ()),
        challenge_profile=args.profile,
        scaled=tuple(int(x) for x in args.scaled.split(",")) if args.profile == "lite-L1" else (),
        reward_policy=args.policy,
        receipt_signer=sc.Keypair.load(Path(args.receipt_key)).public.hex() if args.receipt_key else "",
        reference_features=tuple(args.reference_features or ()),
    )
    Path(args.out).parent.mkdir(parents=True, exist_ok=True)
    Path(args.out).write_text(manifest.to_json())
    _print({"manifest": str(args.out), "manifest_hash": manifest.manifest_hash().hex()})


def _build_references(work: Workdir, manifest) -> dict:
    """Build the ratchet references for this season's constants (deterministic,
    like the baseline). Their hashes are published at open in references.json."""

    target, implied = _build_target(manifest)
    hashes = {}
    for name in manifest.reference_features:
        module = build_solver(target, work.season_rs_file.read_text(), implied + name.split("+"))
        work.references_dir.mkdir(exist_ok=True)
        (work.references_dir / f"{name}.wasm").write_bytes(module)
        hashes[name] = module_sha256(module).hex()
    if hashes:
        (work.path / "references.json").write_text(json.dumps(hashes, indent=2, sort_keys=True) + "\n")
    return hashes


def _check_references(work: Workdir) -> dict:
    """Independent check: rebuild every reference from the pinned source."""

    manifest = work.manifest()
    if not manifest.reference_features:
        return {}
    target, implied = _build_target(manifest)
    out = {}
    for name in manifest.reference_features:
        rebuilt = build_solver(target, work.season_rs_file.read_text(), implied + name.split("+"))
        out[name] = rebuilt == (work.references_dir / f"{name}.wasm").read_bytes()
    return out


def cmd_open(args) -> None:
    work = Workdir(args.workdir)
    work.path.mkdir(parents=True, exist_ok=True)
    manifest = SeasonManifest.load(args.manifest)
    if manifest.baseline_source_sha256 != source_sha256():
        raise SystemExit("starter solver source differs from the manifest pin")
    work.manifest_file.write_text(manifest.to_json())
    beacon = _beacon(args, manifest.challenge_beacon_slot)
    work.beacon_file.write_text(json.dumps(beacon.__dict__) + "\n")
    challenge = season_challenge(manifest, beacon)
    work.write_public_challenge(challenge)
    target, implied = _build_target(manifest)
    baseline = build_solver(target, work.season_rs_file.read_text(), implied)
    work.baseline_file.write_bytes(baseline)
    references = _build_references(work, manifest)
    log = work.log()
    log.open(beacon.bytes(), module_sha256(baseline))
    log.save(work.log_file)
    _print({
        "challenge_id": challenge.challenge_id.hex(),
        "task_spec": challenge.task_spec,
        "baseline_module_sha256": module_sha256(baseline).hex(),
        "reference_module_sha256s": references,
        "log_head": log.head.hex(),
    })


