def _onchain_season(work: Workdir) -> dict | None:
    if not work.chain_file.exists():
        return None
    chain = _chain(work)
    account = sc.Rpc(chain["rpc"]).account(_lite(chain).season(work.manifest().season_id))
    return sc.parse_season(account["raw"]) if account else None


def _epoch_reward(work: Workdir, override: int | None) -> tuple[int | None, str]:
    """The allocation cap of this epoch. With a chain it is the season's
    on-chain close_cap (fixed at chain-close, = ARES unlocked by the schedule
    since the previous settlement, bounded by MAX_EPOCH_SECONDS); nobody
    chooses it. Off-chain runs may pass --epoch-reward explicitly."""

    season = _onchain_season(work)
    if season is not None:
        if season["status"] == "OPEN":
            raise SystemExit("run chain-close first: the epoch cap is fixed when the season is closed on-chain")
        log_head = work.log().entries[-1].head.hex()
        if season["log_head"] != log_head:
            raise SystemExit("on-chain pinned log head differs from the local receipt log")
        if override is not None and override != season["close_cap"]:
            raise SystemExit("--epoch-reward disagrees with the on-chain close_cap")
        return season["close_cap"], "on-chain season.close_cap"
    return override, "--epoch-reward" if override is not None else "manifest season_cap (no chain)"


def cmd_finalize(args) -> None:
    import time

    work = Workdir(args.workdir)
    manifest, log = work.manifest(), work.log()
    close_slot = log.entries[-1].fields[0]
    epoch_reward, source = _epoch_reward(work, args.epoch_reward)
    beacon = _beacon(args, close_slot + manifest.reward_beacon_delay_slots)
    work.reward_beacon_file.write_text(json.dumps(beacon.__dict__) + "\n")
    started = time.monotonic()
    result = finalize(manifest, work.challenge(), log, beacon, work.baseline_file.read_bytes(),
                      work.reference_modules(), epoch_reward)
    elapsed = time.monotonic() - started
    data = json.loads(result.table.to_json())
    data["epoch_reward_cap"] = epoch_reward
    data["epoch_reward_source"] = source
    data["evaluation_cost"] = {  # metadata only: not part of any digest
        "wall_seconds": round(elapsed, 3), "submissions": len(result.evaluations),
        "total_fuel": sum(ev.benchmark_fuel + sum(r.fuel_charged for r in ev.gate_results)
                          for _, _, _, ev in result.evaluations)}
    data["log_head"] = result.log_head.hex()
    data["baseline"] = {"fuel": result.baseline.benchmark_fuel, "evaluation_digest": result.baseline.digest().hex()}
    data["evaluations"] = [
        {"commit_seq": seq, "address": addr.hex(), "address_b58": sc.b58encode(addr), "solution_hash": sol.hex(),
         "valid": ev.valid, "reason": ev.reason, "benchmark_fuel": ev.benchmark_fuel,
         "gate_fuel": [r.fuel_charged for r in ev.gate_results], "evaluation_digest": ev.digest().hex()}
        for seq, addr, sol, ev in result.evaluations
    ]
    data["score_table_digest"] = result.score_digest.hex()
    data["score_table"] = [{"commit_seq": r.commit_seq, "address": r.address.hex(), "solution_hash": r.solution_hash.hex(),
                            "valid": r.valid, "score": r.score} for r in result.score_rows]
    if result.shadow is not None:
        data["shadow_telescoping_v0"] = {"totals": [list(t) for t in result.shadow.totals], "total": result.shadow.total,
                                         "note": "data only; order-dependent (lite/sim/results/reward_order.json)"}
    data["merkle_root"] = result.merkle_root.hex()
    data["profile"] = PROFILE_STATUS
    work.results_file.write_text(json.dumps(data, indent=2, sort_keys=True) + "\n")
    _print({"merkle_root": data["merkle_root"], "total": result.table.total, "epoch_reward_cap": epoch_reward,
            "winners": [sc.b58encode(bytes.fromhex(a)) for a, _ in result.table.totals],
            "score_table_digest": data["score_table_digest"], "log_head": result.log_head.hex()})


def cmd_verify_season(args) -> None:
    """Independent recomputation from public artefacts only."""

    work = Workdir(args.workdir)
    published = json.loads(work.results_file.read_text())
    beacon = Beacon(**json.loads(work.reward_beacon_file.read_text()))
    epoch_reward, _ = _epoch_reward(work, published.get("epoch_reward_cap"))
    result = finalize(work.manifest(), work.challenge(), work.log(), beacon, work.baseline_file.read_bytes(),
                      work.reference_modules(), epoch_reward)
    from ares_lite.transparency import check_closed_log

    entries = [json.loads(line) for line in work.log_file.read_text().splitlines()]
    check_closed_log(entries)
    ok = (
        result.merkle_root.hex() == published["merkle_root"]
        and result.table.digest().hex() == published["table_digest"]
        and result.score_digest.hex() == published.get("score_table_digest", result.score_digest.hex())
        and published["log_head"] == entries[-1]["head"] == result.log_head.hex()
        and published.get("epoch_reward_cap") == epoch_reward
    )
    season = _onchain_season(work)
    if season is not None and season["status"] in ("PUBLISHED", "CORRECTED", "FINAL"):
        ok = ok and season["reward_root"] == result.merkle_root.hex() \
            and season["reward_total"] == result.table.total \
            and season["results_digest"] == result.score_digest.hex()
    references = {} if args.skip_rebuild else _check_references(work)
    ok = ok and all(references.values())
    _print({"reproduced": ok, "merkle_root": result.merkle_root.hex(), "epoch_reward_cap": epoch_reward,
            "references_rebuilt_identically": references or None})
    if not ok:
        raise SystemExit(1)


