def cmd_practice(args) -> None:
    """Self-test on PUBLIC practice seeds (not reward-critical)."""

    work = Workdir(args.workdir)
    manifest, challenge = work.manifest(), work.challenge()
    module = Path(args.module).read_bytes()
    reveal, record = baseline_reveal(manifest, challenge, module)
