def _address(text: str) -> bytes:
    raw = sc.b58decode(text) if len(text) != 64 else bytes.fromhex(text)
    if len(raw) != 32:
        raise SystemExit("address must be a base58 Solana public key")
    return raw


def cmd_commit(args) -> None:
    work = Workdir(args.workdir)
    manifest, challenge = work.manifest(), work.challenge()
    module = Path(args.module).read_bytes()
    address = _address(args.address)
    salt = os.urandom(32)
    solution = canonical_solution(challenge, module)
    commitment = commitment_for(manifest, challenge, address, solution, salt)
    log = work.log()
    entry = log.commit(address, commitment)
    log.save(work.log_file)
    secret = Path(args.secret_out)
    if Path(__file__).resolve().parents[1] in secret.resolve().parents:
        raise SystemExit("keep the reveal secret outside the repository")
    secret.parent.mkdir(parents=True, exist_ok=True)
    receipt = _signed(work, _receipt_key(args.receipt_key), entry)
    secret.write_text(json.dumps({"commit_seq": entry.seq, "salt": salt.hex(), "module": str(Path(args.module).resolve()),
                                  "commit_receipt": receipt}))
    if args.pool or args.agent:
        # Optional, self-declared, never scored and never in the commitment.
        with work.metadata_file.open("a") as fh:
            fh.write(json.dumps({"commit_seq": entry.seq, "address": address.hex(), "pool": args.pool or "",
                                 "ai_agents": sorted(set(args.agent or ()))}, sort_keys=True) + "\n")
    _print({"commit_seq": entry.seq, "commitment": commitment.hex(), "head": entry.head.hex(), "receipt": receipt})


def cmd_reveal(args) -> None:
    work = Workdir(args.workdir)
    manifest, challenge = work.manifest(), work.challenge()
    secret = json.loads(Path(args.secret).read_text())
    module = Path(secret["module"]).read_bytes()
    raw = reveal_bytes_for(manifest, challenge, canonical_solution(challenge, module), bytes.fromhex(secret["salt"]))
    log = work.log()
    entry = log.reveal(secret["commit_seq"], raw)
    log.save(work.log_file)
    receipt = _signed(work, _receipt_key(args.receipt_key), entry)
    if receipt:
        secret["reveal_receipt"] = receipt
        Path(args.secret).write_text(json.dumps(secret))
    _print({"seq": entry.seq, "head": entry.head.hex(), "receipt": receipt})


def cmd_check_receipt(args) -> None:
    """Participant: prove the published log honours my signed receipt."""

    from ares_lite.transparency import SignedReceipt, TransparencyViolation, check_receipt_against_log

    work = Workdir(args.workdir)
    manifest = work.manifest()
    if not manifest.receipt_signer:
        raise SystemExit("this season has no receipt signer")
    secret = json.loads(Path(args.secret).read_text())
    entries = [json.loads(line) for line in work.log_file.read_text().splitlines()]
    report = {}
    for key in ("commit_receipt", "reveal_receipt"):
        if secret.get(key):
            try:
                check_receipt_against_log(bytes.fromhex(manifest.receipt_signer), SignedReceipt.from_json(secret[key]), entries)
                report[key] = "honoured"
            except TransparencyViolation as exc:
                report[key] = f"VIOLATION: {exc}"
    _print(report)


